import argparse,datetime as dt,json
from pathlib import Path

def main():
    p=argparse.ArgumentParser();p.add_argument('results');p.add_argument('--early',required=True);a=p.parse_args();data=json.loads(Path(a.results).read_text());r=data['results'];symbols=('BTCUSDT','ETHUSDT','SOLUSDT')
    dates=[(Path(a.early)/x['file']).stat().st_mtime for x in data['early_manifest']]
    manifest={'source':'https://data.binance.vision/data/spot/monthly/klines','archive_mtime_min_utc':dt.datetime.fromtimestamp(min(dates),dt.timezone.utc).isoformat(),'archive_mtime_max_utc':dt.datetime.fromtimestamp(max(dates),dt.timezone.utc).isoformat(),'files':data['early_manifest']}
    Path('research/donchian_early_manifest.json').write_text(json.dumps(manifest,indent=2)+'\n',encoding='utf8');Path('research/donchian_results_summary.json').write_text(json.dumps(r,indent=2)+'\n',encoding='utf8')
    total=sum(r[f'{s}|all|donchian|10']['net'] for s in symbols);n=sum(r[f'{s}|all|donchian|10']['closed'] for s in symbols);best=max(r[f'{s}|all|donchian|10']['best'] for s in symbols);bestasset=max(r[f'{s}|all|donchian|10']['net'] for s in symbols)
    if n!=29 or not(total>0 and total-best>0 and total-bestasset>0):raise ValueError('Review decision against frozen criteria')
    lines=['# Дневной Donchian60: offline-исследование','',
    '## Решение: Б — результат недостаточно убедителен','',
    f'На непрерывном участке 2024–октябрь 2026 суммарный net трёх отдельных счетов после повышенных издержек составил {total:.4f} USDT, но завершено **{n} сделок** при заранее заданном минимуме 30. Положительный результат сохраняется без лучшей сделки и лучшего актива, однако разрыв мал, SOL отрицателен, а все годы уже использованы в проекте. Это не независимая проверка и не доказательство прибыльности. Ни установка, ни paper-наблюдение не запускаются.','',
    'Один вариант и критерии зафиксированы до вычислений: [DONCHIAN60_PLAN.md](DONCHIAN60_PLAN.md). Размер входа до 10 USDT на отдельном счёте 1000 USDT; без плеча, повторного размера, внутридневного stop 2% и take 4%. Выход по дневному close, исполнение по следующему дневному open. Gap может быть гораздо хуже уровня выхода. Никакие правила работающих служб не менялись.','',
    'В таблицах net на год = изменение equity с оценкой возможного выхода по границам; позиция и уровень не сбрасываются. Реализованный итог — результат сделок с фактическим модельным выходом в этом году, включая входы прошлых лет. Открытый итог — результат всей текущей позиции на конец года с предполагаемыми затратами выхода. Следовательно, годовой net = реализованный + изменение открытого итога. Gross — та же концепция до комиссий и разницы исполнения. Учтённые расходы/оборот — фактические модельные операции за период; разница оценочной стоимости выхода на границах также влияет на net.','',
    '## Годовые результаты Donchian60','',
    '| Актив | Период | Gross | Net базовый / повышенный | Реализовано | Открыто на конец | Оборот | Комиссия + spread/slip | Закрытых сделок |', '|---|---|---:|---:|---:|---:|---:|---:|---:|']
    for s in symbols:
        for y in (2024,2025,2026,'all'):
            x=r[f'{s}|{y}|donchian|5'];z=r[f'{s}|{y}|donchian|10'];lines.append(f"| {s} | {y} | {x['gross']:.4f} | {x['net']:.4f} / {z['net']:.4f} | {x['realised']:.4f} | {x['unrealised_end']:.4f} | {x['turnover']:.2f} | {x['fees']:.4f} + {x['impact']:.4f} | {x['closed']} |")
    lines+=['','`all` — 01.01.2024–01.11.2026 UTC, остальные строки — части одного непрерывного прогона, не отдельные запуски. 2026 — январь–октябрь. Суммы выражены в USDT; net делится на весь счёт, а не на один размер входа.','',
    '| Актив | Период | В позиции % дней | Средняя экспозиция USDT | Длит. закрытой позиции, дней | Средняя net сделка USDT / bps | Просадка счёта % | Убыток позиции от входа % | От пика позиции % | Net без лучшей сделки |', '|---|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for s in symbols:
        for y in (2024,2025,2026,'all'):
            x=r[f'{s}|{y}|donchian|5'];mean='—' if x['avg_net'] is None else f"{x['avg_net']:.4f} / {x['avg_bps']:.1f}";dur='—' if x['avg_holding_days'] is None else f"{x['avg_holding_days']:.1f}";nb='—' if x['without_best'] is None else f"{x['without_best']:.4f}"
            lines.append(f"| {s} | {y} | {x['exposure_pct']:.1f} | {x['mean_exposure']:.3f} | {dur} | {mean} | {x['account_dd_pct']:.3f} | {x['position_adverse_pct']:.2f} | {x['position_peak_dd_pct']:.2f} | {nb} |")
    lines+=['','Все просадки и экспозиция измерены на дневных закрытиях; внутридневные потери и разрывы могут быть больше. Убыток позиции — максимум относительно уплаченной при входе суммы, с модельными затратами выхода; отдельно показан откат от максимума стоимости позиции. Средняя длительность и bps считаются по завершённым сделкам, открытые в конце не подменяются закрытыми.','',
    '| Период | Суммарный net, базовый / стресс | Стресс без лучшей сделки | Стресс без лучшего актива | Закрытых сделок |', '|---|---:|---:|---:|---:|']
    for y in (2024,2025,2026,'all'):
        base=[r[f'{s}|{y}|donchian|5'] for s in symbols];stress=[r[f'{s}|{y}|donchian|10'] for s in symbols];snet=sum(x['net'] for x in stress);best=max((x['best'] for x in stress if x['best'] is not None),default=0);bestasset=max(x['net'] for x in stress)
        lines.append(f"| {y} | {sum(x['net'] for x in base):.4f} / {snet:.4f} | {snet-best:.4f} | {snet-bestasset:.4f} | {sum(x['closed'] for x in stress)} |")
    lines+=['','| Период | Gross сумма | Реализовано / открыто на конец | Оборот | Комиссия + spread/slip | Средняя экспозиция трёх счетов | Ожидание USDT / bps | Среднее удержание дней | Худшая просадка отдельного счёта / позиции % |', '|---|---:|---:|---:|---:|---:|---:|---:|---:|']
    for y in (2024,2025,2026,'all'):
        x=[r[f'{s}|{y}|donchian|5'] for s in symbols];count=sum(z['closed'] for z in x);avg=sum((z['avg_net'] or 0)*z['closed'] for z in x)/count if count else 0;bps=sum((z['avg_bps'] or 0)*z['closed'] for z in x)/count if count else 0;duration=sum((z['avg_holding_days'] or 0)*z['closed'] for z in x)/count if count else 0
        lines.append(f"| {y} | {sum(z['gross'] for z in x):.4f} | {sum(z['realised'] for z in x):.4f} / {sum(z['unrealised_end'] for z in x):.4f} | {sum(z['turnover'] for z in x):.2f} | {sum(z['fees'] for z in x):.4f} + {sum(z['impact'] for z in x):.4f} | {sum(z['mean_exposure'] for z in x):.4f} USDT | {avg:.4f} / {bps:.1f} | {duration:.1f} | {max(z['account_dd_pct'] for z in x):.3f} / {max(z['position_adverse_pct'] for z in x):.2f} |")
    lines+=['','Это сложение PnL трёх счетов, а не доходность одного счёта. Без лучшей сделки из годового результата вычитается net сделки, закрытой в данном году, включая её доход до границы; это стресс-концентрация, а не альтернативный путевой backtest.','',
    '## Равный размер: сравнение за весь основной период','',
    '| Актив | Donchian net / стресс | SMA10/30 15m net / стресс | Buy-and-hold net / стресс | Cash net | Raw equity / equity с модельным выходом Donchian |', '|---|---:|---:|---:|---:|---:|']
    for s in symbols:
        v=lambda name,b:r[f'{s}|all|{name}|{b}'];x=v('donchian',5)
        lines.append(f"| {s} | {x['net']:.4f} / {v('donchian',10)['net']:.4f} | {v('sma',5)['net']:.4f} / {v('sma',10)['net']:.4f} | {v('hold',5)['net']:.4f} / {v('hold',10)['net']:.4f} | {v('none',5)['net']:.4f} | {x['raw_equity_end']:.4f} / {x['liquidation_equity_end']:.4f} |")
    lines+=['','Buy-and-hold покупает тот же номинал при начале периода и держит; сумма выхода на конец — модельная оценка. SMA использует 15m сигнал и прежние stop 2% / take 4%, непрерывное состояние между годами и те же расходы. Разная частота и риск являются частью сравниваемых правил; равный номинал не делает их рыночный риск одинаковым.','',
    '## Дополнительный сегмент 2021–2022','',
    'Дневные архивы Binance 1d проверены отдельно; прогрев с ноября 2020. Непрерывного переноса через 2023 нет: в мартовских 15m данных есть разрыв. Выбор сегодняшних BTC/ETH/SOL и правила после публикаций создаёт survivorship и selection bias. Это не независимый тест. Исторического 15m SMA-бенчмарка для этого сегмента не загружали.','',
    '| Актив | Donchian net base / стресс | Закрыто | Buy-and-hold net base / стресс | Cash |', '|---|---:|---:|---:|---:|']
    for s in symbols:
        x=r[f'{s}|2021-22|donchian|5'];z=r[f'{s}|2021-22|donchian|10'];h=r[f'{s}|2021-22|hold|5'];hh=r[f'{s}|2021-22|hold|10'];lines.append(f"| {s} | {x['net']:.4f} / {z['net']:.4f} | {x['closed']} | {h['net']:.4f} / {hh['net']:.4f} | 0 |")
    lines+=['','## Данные, источники и границы','',
    'Основной прогон: проверенные SHA-256 локальные Binance 15m, преобразованы в UTC-дни только при наличии ровно 96 последовательных свечей. Исторический разрыв 24.03.2023 исключён; последующий полный участок использован для прогрева. 2026 ограничен 31 октября включительно. Данные 2021–2022: официальные Binance 1d, сверенные с опубликованными CHECKSUM, без заполнения пропусков; список и хеши — [манифест](research/donchian_early_manifest.json). Более ранние данные и 2024–2026 не являются независимыми.','',
    '[Catching Crypto Trends](https://concretumgroup.com/wp-content/uploads/2026/02/Catching-Crypto-Trends.pdf) рассматривает ансамбль каналов, ротацию и volatility sizing; это не воспроизводится здесь. В статье вход описан как достижение верхней границы; здесь по заданию используется строгое превышение максимума предыдущих 60 дней, что отличается на равенстве. [Gerritsen и соавторы](https://research-portal.uu.nl/en/publications/the-profitability-of-technical-trading-rules-in-the-bitcoin-marke/) исследовали дневные технические правила BTC. [Hudson и Urquhart](https://research.birmingham.ac.uk/en/publications/technical-trading-and-cryptocurrencies/) отмечали отсутствие предсказательной способности BTC на их out-of-sample. Ни одна из работ не подтверждает этот упрощённый кандидат.','',
    'Стандартная модель на сторону: комиссия 10 bps + spread/slippage 5 bps, стресс 10 + 10 bps. Биржевые исторические фильтры, ликвидность, задержка, проскальзывание при крупных разрывах и доступность исполнения не реконструированы. Дневной close не защищает от внутридневных потерь. Состояние текущих paper-рынков не проверялось и не менялось.','',
    'Воспроизведение: `PYTHONPATH=. python3 -B research/donchian60.py --data /путь/15m --early /путь/1d --early-manifest research/donchian_early_manifest.json --output /путь/results.json`. Отсутствующие ранние архивы загружаются и проверяются по опубликованным и сохранённым SHA-256; 15m архивы и их манифесты должны быть восстановлены отдельно по прежним инструкциям. `python3 research/write_donchian_report.py /путь/results.json --early /путь/1d` создаёт отчёт. Тесты: `PYTHONPATH=. python3 -B -m unittest tests.test_donchian60 -q`. Архивы и большие ряды не входят в Git.']
    Path('DONCHIAN60_RESEARCH_2026_11_05.md').write_text('\n'.join(lines)+'\n',encoding='utf8')
if __name__=='__main__':main()
